import { SessionPartTrackerEvents, TrackVisitorType, ONE_TICK_DURATION, TIMEOUT_FOR_END_TRACK, TIMEOUT_FOR_REQUEST, RETRY_REQUEST } from '../../constants/sessions.js';

class VisitorTrackerService{start(){this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerEndEvent].add(this.partEnd);this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerPartGoing].add(this.partGoing);void this.sendStats(TrackVisitorType.Open);}destroy(){this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerEndEvent].remove(this.partEnd);this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerPartGoing].remove(this.partGoing);void this.sendStats(TrackVisitorType.Close);}constructor(i){this.partGoing=()=>{this.totalActiveDuration+=ONE_TICK_DURATION;if(this.totalActiveDuration>=TIMEOUT_FOR_END_TRACK&&this.durationAfterRequest<TIMEOUT_FOR_REQUEST){return}this.durationAfterRequest+=ONE_TICK_DURATION;if(this.durationAfterRequest>=TIMEOUT_FOR_REQUEST){this.durationAfterRequest-=TIMEOUT_FOR_REQUEST;void this.sendStats(TrackVisitorType.Activity);}};this.partEnd=s=>{const i=s.duration%ONE_TICK_DURATION;this.totalActiveDuration+=i;if(this.totalActiveDuration<TIMEOUT_FOR_END_TRACK){this.durationAfterRequest+=i;}};this.sendStats=async(t,i)=>{const e=()=>{!i&&setTimeout(()=>void this.sendStats(t,true),RETRY_REQUEST);};try{await this.requestApiMethod("stats.trackVisitor",{app_id:this.appId,session_uuid:this.sessionUuid,session_duration:this.totalActiveDuration,type:t});}catch{e();}};this.sessionUuid=i.sessionUuid;this.appId=i.appId;this.requestApiMethod=i.requestApiMethod;this.eventHooks=i.eventHooks;this.totalActiveDuration=0;this.durationAfterRequest=0;}}

export { VisitorTrackerService };
